def load() -> pd.DataFrame:
    import openpyxl

    wb = openpyxl.load_workbook('data/biomedical/input/1-s2.0-S0092867420301070-mmc3.xlsx')
    sheet_names = wb.sheetnames

    results = []
    for sheet_name in sheet_names:
        df = pd.read_excel('data/biomedical/input/1-s2.0-S0092867420301070-mmc3.xlsx', sheet_name=sheet_name, nrows=3)
        results.append({
            'Sheet': sheet_name,
            'Columns': ', '.join(df.columns.tolist()),
            'Rows': len(df)
        })

    return pd.DataFrame(results)

def process(load_fdr_sheet) -> pd.DataFrame:
    cbx3_data = load_fdr_sheet[load_fdr_sheet['Gene'] == 'CBX3']
    return cbx3_data

def process(load_fdr_sheet) -> pd.DataFrame:
    rest_data = load_fdr_sheet[load_fdr_sheet['Gene'] != 'CBX3']
    return rest_data

def process(cbx3_fdr) -> pd.DataFrame:
    avg_fdr = cbx3_fdr['FDR.phos'].mean()
    return pd.DataFrame({'CBX3_avg_FDR': [avg_fdr]})

def process(rest_genes_fdr) -> pd.DataFrame:
    avg_fdr = rest_genes_fdr['FDR.phos'].mean()
    return pd.DataFrame({'rest_avg_FDR': [avg_fdr]})

def process(cbx3_avg_fdr, rest_avg_fdr) -> pd.DataFrame:
    cbx3_avg = cbx3_avg_fdr.loc[0, 'CBX3_avg_FDR']
    rest_avg = rest_avg_fdr.loc[0, 'rest_avg_FDR']
    difference = cbx3_avg - rest_avg
    return pd.DataFrame({'FDR_difference': [difference]})
